/* From Uiverse.io by vinodjangid07  - Tags: input, message, send, image, upload, file */
.__UIV_SCOPE__ .messageBox {
  width: fit-content;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #2d2d2d;
  padding: 0 15px;
  border-radius: 10px;
  border: 1px solid rgb(63, 63, 63);
}
.__UIV_SCOPE__ .messageBox:focus-within {
  border: 1px solid rgb(110, 110, 110);
}
.__UIV_SCOPE__ .fileUploadWrapper {
  width: fit-content;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Arial, Helvetica, sans-serif;
}

.__UIV_SCOPE__ #file {
  display: none;
}
.__UIV_SCOPE__ .fileUploadWrapper label {
  cursor: pointer;
  width: fit-content;
  height: fit-content;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.__UIV_SCOPE__ .fileUploadWrapper label svg {
  height: 18px;
}
.__UIV_SCOPE__ .fileUploadWrapper label svg path {
  transition: all 0.3s;
}
.__UIV_SCOPE__ .fileUploadWrapper label svg circle {
  transition: all 0.3s;
}
.__UIV_SCOPE__ .fileUploadWrapper label:hover svg path {
  stroke: #fff;
}
.__UIV_SCOPE__ .fileUploadWrapper label:hover svg circle {
  stroke: #fff;
  fill: #3c3c3c;
}
.__UIV_SCOPE__ .fileUploadWrapper label:hover .tooltip {
  display: block;
  opacity: 1;
}
.__UIV_SCOPE__ .tooltip {
  position: absolute;
  top: -40px;
  display: none;
  opacity: 0;
  color: white;
  font-size: 10px;
  text-wrap: nowrap;
  background-color: #000;
  padding: 6px 10px;
  border: 1px solid #3c3c3c;
  border-radius: 5px;
  box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.596);
  transition: all 0.3s;
}
.__UIV_SCOPE__ #messageInput {
  width: 200px;
  height: 100%;
  background-color: transparent;
  outline: none;
  border: none;
  padding-left: 10px;
  color: white;
}
.__UIV_SCOPE__ #messageInput:focus ~ #sendButton svg path,
.__UIV_SCOPE__ #messageInput:valid ~ #sendButton svg path {
  fill: #3c3c3c;
  stroke: white;
}

.__UIV_SCOPE__ #sendButton {
  width: fit-content;
  height: 100%;
  background-color: transparent;
  outline: none;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s;
}
.__UIV_SCOPE__ #sendButton svg {
  height: 18px;
  transition: all 0.3s;
}
.__UIV_SCOPE__ #sendButton svg path {
  transition: all 0.3s;
}
.__UIV_SCOPE__ #sendButton:hover svg path {
  fill: #3c3c3c;
  stroke: white;
}
